function slug(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function longBreakdown(ch) {
  const lineA = `The request walks into a room that is already leaning toward ${ch.idea.split(" ")[0]}.`;
  const lineB = `The first cue does not win by force; it changes what feels worth checking.`;
  const lineC = `Use the setup to help people see the real choice, not to hide it.`;
  const fast = [
    `At 8:10 a.m., a person sees ${ch.object} before the ask. The ask lands in a mind that is already tilted. ${lineA} Put one true cue in view first. Then ask in plain words. The cue should help them see the choice, not push them past it. If the cue adds fear or haze, change it.`,
    `Use the setup with care. Ask what they will see, hear, or touch first. If that thing helps them weigh the facts, keep it. If it pulls them toward fear, pride, haste, or fog, move it before you ask.`
  ].join("\n\n");
  const deep = [
    `At 2:25 p.m., picture a supervisor pausing before a hard request. The words are ready, but the room is not. A phone buzzes, a chair scrapes, and the first object in view is already telling people what kind of moment this is. ${lineB}`,
    `A cue works because the mind does not wait for the full argument. It grabs what is near, vivid, repeated, personal, or shared, then uses that cue to judge what follows. That can help a good case. It can also make a weak case feel stronger than it is. The useful test is whether the cue points toward the facts people need or away from them.`,
    `Picture a client walking in with wet shoes and five spare minutes. The slide deck may be sound, but the first thing she sees may be a late fee, a crowded room, or a proud award wall that has nothing to do with her problem. Change that first sight. Put the broken part, the fair price range, the patient note, or the shared task where her eyes will go.`,
    `Try the move in a live setting. Before asking, name what the listener is likely to notice first. If that first notice helps them judge well, keep it. If it pulls them toward fear, vanity, hurry, or false comfort, change the setting. ${lineC}`
  ].join("\n\n");
  const full = [
    `At 7:42 a.m., a team gathers around a table with coffee rings, open laptops, and one object no one can ignore: ${ch.object}. Before the leader speaks, the object has done some of the work. It has told the room where to look. It has made one concern feel near and another feel far away. That is why ${ch.idea}.`,
    `A mind under pressure does not sort every fact from scratch. It uses cues. A first number becomes a comparison. A trusted face softens a later claim. A shared task makes a later request feel less like an outside demand. A charged image can make a risk feel huge. None of these cues replaces substance. They change the conditions in which substance is judged.`,
    `A good setup earns attention for the right reason. If a tenant needs to see the broken stair before voting on repairs, take the meeting to the stairwell. If a patient is scared by a machine, name the fear before explaining the scan. If a donor needs to remember why the program matters, put the student's work in front of her before the gift amount. The cue should help the person see more clearly.`,
    `You can spot the bad version by the aftertaste it leaves. The person says yes fast, then later feels steered. The room applauds, then cannot explain the choice. The customer signs, then calls back confused. Those are signs that the setup was stronger than the case. A sound setup makes the later facts easier to face, not harder to inspect.`,
    `Hand the listener a better first frame. Show the actual crack before the repair quote. Move the talk out of the hallway if the hallway cues fear. Ask people to sort one card together before asking them to own the plan. Small changes like these work because they meet the mind before it has settled on what matters.`,
    `There is a limit, and it matters in daily work. A setup becomes suspect when it hides cost, fakes urgency, borrows trust that was not earned, or makes a person choose while too stirred up to think. The same method can clarify or cloud. The difference is whether the person would still thank you for the setup after seeing the full facts.`,
    `At the end, keep the move modest. You are not trying to win by mood alone. You are trying to give the real issue a fair first place in the person's mind. If the first cue is true, relevant, and kind to the choice in front of them, use it. If it only makes the yes easier for you, take it out.`,
    `Before the next important ask, do a thirty-second audit. What will they see first? What feeling will that create? What comparison will be active? What identity will be touched? Then change one thing so the first cue serves the real decision. ${lineC}`
  ].join("\n\n");
  return { fast, deep, full, lines: [lineA, lineB, lineC] };
}

function makeQuiz(ch) {
  const blooms = ["apply", "analyze", "evaluate", "create", "understand", "apply", "analyze", "evaluate", "create"];
  const depths = ["simple", "standard", "deep", "standard", "simple", "standard", "deep", "standard", "deep"];
  const openers = [
    "A manager is about to ask a tired team to adopt a new process after a messy outage, and the first thing on the screen is a dense policy page.",
    "If you are advising a clinic director who wants patients to make a careful choice, the waiting room is filled with glossy ads for one option.",
    "A teacher wants students to care about a safety rule after recess, and the broken equipment is still sitting beside the playground gate.",
    "Which action best fits a city planner who needs shop owners to judge a street change fairly while rumors are spreading before the meeting?",
    "A parent needs a teenager to agree to a driving rule, but the conversation starts while both are angry in the driveway.",
    "A designer is reviewing a sign-up flow and sees that users click yes quickly but misunderstand what happens next.",
    "A coach has one minute before a team vote, and the athletes are focused on the loudest player instead of the full practice pattern.",
    "Someone on a hiring panel keeps returning to a candidate's polished slide deck even though the work sample is weaker.",
    "Which plan best helps a nonprofit ask for support while keeping the listener free to judge the real value of the work?"
  ];
  return {
    passingScorePercent: 80,
    questions: openers.map((p, i) => {
      const correct = i % 3;
      const choices = [
        "Add more facts immediately and trust the listener to sort the setup out later.",
        `Change the first cue so it supports the real decision, then make the request in plain words.`,
        "Use the strongest emotional cue available, even if it is only loosely connected to the choice."
      ];
      if (correct !== 1) {
        const tmp = choices[correct];
        choices[correct] = choices[1];
        choices[1] = tmp;
      }
      return {
        questionId: `ch${String(ch.n).padStart(2, "0")}-q${String(i + 1).padStart(2, "0")}`,
        prompt: `${p} What should happen first if the goal is to use ${ch.idea} without clouding judgment?`,
        choices,
        correctIndex: correct,
        explanation: `The best answer adjusts the cue before the ask while keeping the real choice visible. It uses ${ch.move}, instead of adding pressure or piling on facts too late.`,
        bloomsLevel: blooms[i],
        depthLevel: depths[i],
      };
    }),
  };
}

function makeCards(ch) {
  return [
    {
      cardId: `ch${String(ch.n).padStart(2, "0")}-rc01`,
      front: `You are about to make a request. What should you inspect before the first sentence?`,
      back: `Inspect the first cue: what the listener will see, feel, compare, or identify with before the ask. Change it if it pulls attention away from the real choice.`,
      difficulty: "easy",
    },
    {
      cardId: `ch${String(ch.n).padStart(2, "0")}-rc02`,
      front: `A cue gets attention but also makes the choice feel rushed. What is the repair?`,
      back: `Keep only cues that help people judge well. Slow the moment down, add missing facts, or move the cue out of first position if it creates pressure without clarity.`,
      difficulty: "medium",
    },
    {
      cardId: `ch${String(ch.n).padStart(2, "0")}-rc03`,
      front: `A team agrees in the room, then forgets by tomorrow. What did the setup miss?`,
      back: `The yes needed an after-cue: a visible next step, a calendar hold, a shared note, or a first action before the room broke apart.`,
      difficulty: "medium",
    },
    {
      cardId: `ch${String(ch.n).padStart(2, "0")}-rc04`,
      front: `When does a strong setup become unethical?`,
      back: `It crosses the line when it hides cost, fakes urgency, borrows trust, or makes a weaker offer feel stronger than the facts support.`,
      difficulty: "hard",
    },
  ];
}

function makePlan(ch) {
  return {
    coreSkill: `The core skill is setup judgment. Before you ask, choose the cue, place, timing, or shared action that helps the other person see the real choice clearly.`,
    ifThenPlans: [
      { context: "work", plan: `If I need a decision at work, then I will check what the room sees first and move one object, slide, or number so it supports ${ch.move}.` },
      { context: "health", plan: `If a health choice is coming, then I will remove cues that create panic and put the most relevant evidence where the person can see it before deciding.` },
      { context: "personal", plan: `If I am making a personal ask, then I will start with shared purpose and one concrete object instead of old frustration or vague pressure.` },
      { context: "relationships", plan: `If someone says yes to a change, then I will help set the first cue for follow-through before we leave the conversation.` },
    ],
    twentyFourHourChallenge: `Within the next 24 hours, choose one real ask and write down the first thing the other person will see, hear, or compare. Change one cue so the setup helps them judge the choice fairly.`,
    weeklyPractice: `Once this week, review one request that worked or failed. Separate the ask from the setup, then name the cue that shaped the result most.`,
  };
}

function makeChapter(ch) {
  const b = longBreakdown(ch);
  const chapterId = `${BOOK_ID}-ch${String(ch.n).padStart(2, "0")}`;
  return {
    chapterId,
    number: ch.n,
    title: ch.title,
    readingTimeMinutes: 12,
    hook: ch.hook,
    counterintuition: ch.counter,
    tryThisNow: `Before your next request, move one cue: the first object, first number, first place, or first shared action. Make it serve the real decision.`,
    keyTakeaway: `People rarely meet an ask in neutral air, so prepare the first cue, place, or shared action to support clear judgment before you rely on better wording.`,
    breakdown: {
      fastRead: b.fast,
      deepRead: b.deep,
      fullRead: b.full,
    },
    examples: ch.examples.map((e, i) => {
      const [format, name, title, domain, audience, setting, scenario, whatToDo, whyItMatters] = e;
      return {
        exampleId: `ch${String(ch.n).padStart(2, "0")}-ex${String(i + 1).padStart(2, "0")}-${slug(name)}-${slug(title).split("-").slice(1, 4).join("-")}`,
        title,
        tags: [format, slug(domain).slice(0, 32), "pre-suasion"],
        planSpec: {
          domain,
          audience,
          stakes: "whether the setup helps the person judge the choice clearly or tilts the moment in a misleading way",
          format,
          requiredBeat: setting,
        },
        scenario,
        whatToDo,
        whyItMatters,
      };
    }),
    quiz: makeQuiz(ch),
    reviewCards: makeCards(ch),
    implementationPlan: makePlan(ch),
    memorableLines: b.lines.map((line, i) => ({
      text: line,
      location: i === 0 ? "breakdown.fastRead" : i === 1 ? "breakdown.deepRead" : "breakdown.fullRead",
      why: "It turns the idea into a short rule the reader can carry into a live request.",
    })),
  };
}

mkdirSync(CHAPTER_DIR, { recursive: true });
mkdirSync(resolve(STATE, "books"), { recursive: true });

for (const ch of chapters) {
  const out = makeChapter(ch);
  const path = resolve(CHAPTER_DIR, `${out.chapterId}.v21-native.chapter.json`);
  writeFileSync(path, JSON.stringify(out, null, 2) + "\n", "utf8");
}

writeFileSync(
  resolve(STATE, "books", `${BOOK_ID}.categories.json`),
  JSON.stringify(
    {
      categories: ["Psychology", "Communication", "Self-Help", "Leadership"],
      tags: ["persuasion", "attention", "influence", "ethics", "priming", "unity"],
    },
    null,
    2,
  ) + "\n",
  "utf8",
);

console.log(`Wrote ${chapters.length} ${TITLE} v21 chapter sidecars.`);
